    ObjectNode snapshot = (ObjectNode) json.readTree(patternSnapshot());
    assertTrue(builder.build(List.of(source(1, "r2", "PATTERN", snapshot.toString())))
            .facts().get(1).text().contains("需结合调用方确认"));
